import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sehatak/app_router.dart';import 'package:sehatak/core/models/child/child_models.dart';import 'package:sehatak/core/services/child_service.dart';class ChildClinicsScreen extends StatelessWidget{const ChildClinicsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('عيادات الأطفال')),body:StreamBuilder<List<ChildClinic>>(stream:ChildService().streamClinics(limit:20),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ListTile(onTap:()=>c.push(AppRouter.childClinicDetail.replaceFirst(':id',d.id)),leading:const Icon(Icons.local_hospital,color:Color(0xFF00BCD4)),title:Text(d.name),subtitle:Text('${d.type} • ${d.address}'),trailing:Text(d.isOpen?'مفتوح':'مغلق')))).toList());}));}}
